        const solidPoints = `${point(topLeft, "ㄱ", -12, -8)}${point(topFront, "ㄴ", -11, 1)}${point(topRight, "ㄷ", 12, -8)}${point(bottomLeft, "ㄹ", -13, 7)}${point(bottomFront, "ㅁ", 0, 17)}${point(bottomRight, "ㅂ", 13, 7)}${point(pointS, "ㅅ", -13, 4)}${point(pointO, "ㅇ", 13, 4)}`;
