          { values: [700, 840, 1200, 1500, 20, 25, 5, 1], names: ["과자", "음료수"] },
          { values: [800, 1000, 1500, 1770, 25, 18, 7, 0], names: ["과자", "음료수"] },
          { values: [1200, 1380, 900, 1080, 15, 20, 5, 1], names: ["과자", "음료수"] }
